sp_widget.client_script:
function($scope, $rootScope, $timeout) {
  var c = this;

  c.selectedYear = "";

  function atualizarIndicador() {
    c.server.get({ selectedYear: c.selectedYear }).then(function(response) {
      c.data = response.data;
      console.log("Indicador Poupança atualizado:", c.selectedYear, c.data);
    });
  }

  // Recebe o ano vindo de outro widget
  $rootScope.$on('anoSelecionado', function(event, ano) {
    c.selectedYear = ano;
    atualizarIndicador();
  });

  // Primeira carga
  atualizarIndicador();
}

sp_widget.css:
.financial-widget {
    border: 1px solid #ccc;
    border-radius: 4px;
    overflow: hidden;
  	margin-top: 4rem;
}

.indicator-block {
    text-align: center;
    padding: 0;
}

.indicator-header {
		background-color: #EBEDF1;
    color: #021770;
    font-weight: 400;
    padding: .8rem 1rem;
    font-size: 1.4rem;
    border-bottom: .1rem solid #C7C7C7
}

.indicator-value {
    color: #021770;
    font-size: 32px;
    font-weight: 400;
    padding: 10px 10px 15px;
}

.separator {
    margin: 0;
    border: 0;
    border-top: 1px solid #e0e0e0;
}

sp_widget.script:
(function() {

  input = input || {};
  var table = 'x_sded9_portal_t_0_capacidade_de_pagamento';

  var selectedYear = input.selectedYear || "";

  // Se nenhum ano vier, pega o mais recente
  if (!selectedYear) {
    var g = new GlideRecord(table);
    g.orderByDesc('u_ano');
    g.setLimit(1);
    g.query();
    if (g.next())
      selectedYear = g.getValue('u_ano');
  }

  data.selectedYear = selectedYear;

  data.indicator = {
    poupanca: { value: '0%', label: 'Poupança Corrente: ' + selectedYear }
  };

  var gr = new GlideRecord(table);

  if (selectedYear)
    gr.addQuery('u_ano', selectedYear);

  gr.orderByDesc('sys_created_on');
  gr.setLimit(1);
  gr.query();

  if (gr.next()) {
    var anoReal = gr.getValue('u_ano');

    data.indicator.poupanca.value = gr.u_poupanca_corrente + '%';
    data.indicator.poupanca.label = 'Poupança Corrente: ' + anoReal;

    data.selectedYear = anoReal;
  }

})();
